package com.narudzbine.audit.api;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronizationManager;
class IndependentEvidenceTest {
 private final Memory store=new Memory();private final byte[] plain="Synthetic evidence Čaj 🍵".getBytes(java.nio.charset.StandardCharsets.UTF_8);
 private static byte[] key(int value){byte[] bytes=new byte[32];Arrays.fill(bytes,(byte)value);return bytes;}
 private final IndependentObjects.Key identity=new IndependentObjects.Key(IndependentObjects.Family.DELETION_INTENT,UUID.fromString("019a0000-0000-7000-8000-000000000001"),1);
 private IndependentEvidence evidence(){return new IndependentEvidence(store,Map.of("v1",key(1)),"v1",List.of(key(9)));}
 @Test void verifiedCreateAndSameContentReplayKeepTheOriginalCiphertextReceipt(){var service=evidence();var first=service.ensure(identity,plain);byte[] bytes=store.values.get(identity).clone();assertThat(first).isEqualTo(service.ensure(identity,plain));assertThat(store.creates).isEqualTo(1);assertThat(store.values.get(identity)).isEqualTo(bytes);assertThat(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).doesNotContain("Synthetic evidence");assertThat(service.read(identity).orElseThrow().bytes()).isEqualTo(plain);}
 @Test void conflictingContentCannotReplaceAnExistingIdentity(){var service=evidence();service.ensure(identity,plain);byte[] before=store.values.get(identity).clone();assertThatThrownBy(()->service.ensure(identity,new byte[]{1})).isInstanceOf(EvidenceFailure.class).extracting(e->((EvidenceFailure)e).code()).isEqualTo("EVIDENCE_IDENTITY_CONFLICT");assertThat(store.values.get(identity)).isEqualTo(before);assertThat(store.creates).isEqualTo(1);}
 @Test void unknownCreateWithRetainedObjectResolvesByReadBackWithoutAnotherPut(){store.lose=true;var receipt=evidence().ensure(identity,plain);assertThat(receipt.ciphertextSha256()).isEqualTo(IndependentEvidence.hash(store.values.get(identity)));assertThat(store.creates).isEqualTo(1);}
 @Test void unknownCreateWithoutRetainedObjectNeverIssuesAVerifiedReceipt(){store.lose=true;store.discard=true;assertThatThrownBy(()->evidence().ensure(identity,plain)).isInstanceOf(EvidenceFailure.class);assertThat(store.creates).isEqualTo(1);assertThat(store.values).isEmpty();}
 @Test void readBackMutationFailsClosed(){store.corrupt=true;assertThatThrownBy(()->evidence().ensure(identity,plain)).isInstanceOf(EvidenceFailure.class);assertThat(store.creates).isEqualTo(1);}
 @Test void corruptionWrongKeysAndCrossIdentityCopiesAreRejected(){var service=evidence();service.ensure(identity,plain);byte[] good=store.values.get(identity).clone();good[good.length-1]^=1;store.values.put(identity,good);assertThatThrownBy(()->service.read(identity)).isInstanceOf(EvidenceFailure.class);store.values.clear();service.ensure(identity,plain);
  var wrong=new IndependentEvidence(store,Map.of("v1",key(2)),"v1",List.of());assertThatThrownBy(()->wrong.read(identity)).isInstanceOf(EvidenceFailure.class);
  for(var changed:List.of(new IndependentObjects.Key(identity.family(),identity.resource(),2),new IndependentObjects.Key(IndependentObjects.Family.DELETION_COMPLETION,identity.resource(),1),new IndependentObjects.Key(identity.family(),UUID.fromString("019a0000-0000-7000-8000-000000000002"),1))){store.values.put(changed,store.values.get(identity).clone());assertThatThrownBy(()->service.read(changed)).isInstanceOf(EvidenceFailure.class);}
 }
 @Test void keyRotationReadsRetainedVersionsAndWritesOnlyTheActiveVersion(){var old=evidence();var receipt=old.ensure(identity,plain);var next=new IndependentEvidence(store,Map.of("v1",key(1),"v2",key(2)),"v2",List.of());assertThat(next.ensure(identity,plain)).isEqualTo(receipt);var id=new IndependentObjects.Key(identity.family(),identity.resource(),2);assertThat(next.ensure(id,plain).keyVersion()).isEqualTo("v2");assertThat(next.read(identity).orElseThrow().keyVersion()).isEqualTo("v1");assertThatThrownBy(()->new IndependentEvidence(store,Map.of("v2",key(2)),"v2",List.of()).read(identity)).isInstanceOf(EvidenceFailure.class);}
 @Test void explicitKeyRingRejectsAliasesArtifactReuseAndInvalidLengths(){assertThatThrownBy(()->new IndependentEvidence(store,Map.of("v1",key(1)),"v1",List.of(key(1)))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new IndependentEvidence(store,Map.of("v1",key(1),"v2",key(1)),"v2",List.of())).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new IndependentEvidence(store,Map.of("v1",new byte[31]),"v1",List.of())).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new IndependentEvidence(store,Map.of("../escape",key(1)),"../escape",List.of())).isInstanceOf(IllegalArgumentException.class);}
 @Test void malformedFramesAndSizeBoundsFailBeforeExposure(){var service=evidence();for(byte[] invalid:List.of(new byte[0],new byte[36],new byte[IndependentObjects.MAX_OBJECT+1])){store.values.put(identity,invalid);assertThatThrownBy(()->service.read(identity)).isInstanceOf(EvidenceFailure.class);}assertThatThrownBy(()->service.ensure(identity,new byte[IndependentObjects.MAX_PLAINTEXT+1])).isInstanceOf(EvidenceFailure.class);assertThat(store.creates).isZero();}
 @Test void defensiveCopiesKeepKeysAndReturnedPlaintextPrivate(){byte[] supplied=key(1);var service=new IndependentEvidence(store,Map.of("v1",supplied),"v1",List.of());supplied[0]=0;service.ensure(identity,plain);var value=service.read(identity).orElseThrow();byte[] changed=value.bytes();changed[0]=0;assertThat(value.bytes()).isEqualTo(plain);assertThat(value.toString()).doesNotContain("Synthetic");}
 @Test void evidenceIoIsForbiddenInsideTransactions(){TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThatThrownBy(()->evidence().ensure(identity,plain)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->evidence().read(identity)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->evidence().list(identity.family(),1,null)).isInstanceOf(IllegalStateException.class);}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}assertThat(store.creates).isZero();}
 @Test void identitiesRejectTraversalNonResourceUuidsAndAmbiguousSequences(){assertThat(IndependentObjects.Key.parse(identity.family(),identity.path())).isEqualTo(identity);for(String path:List.of("../escape",identity.path().replace("0000000001.bin","1.bin"),identity.path().replace("0000000001.bin","0000000000.bin"),identity.path()+"/extra"))assertThatThrownBy(()->IndependentObjects.Key.parse(identity.family(),path)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new IndependentObjects.Key(identity.family(),UUID.randomUUID(),1)).isInstanceOf(IllegalArgumentException.class);}
 @Test void knownReceiptReadNeverCreatesMissingOrConflictingReplacement(){var e=evidence();var receipt=e.ensure(identity,plain);assertThat(e.require(identity,plain,receipt)).isEqualTo(receipt);assertThat(store.creates).isEqualTo(1);byte[] original=store.values.remove(identity);assertThatThrownBy(()->e.require(identity,plain,receipt)).isInstanceOf(EvidenceFailure.class).extracting(f->((EvidenceFailure)f).code()).isEqualTo("EVIDENCE_MISSING");assertThat(store.creates).isEqualTo(1);store.values.put(identity,original);var other=new IndependentEvidence.Receipt(identity,receipt.keyVersion(),"0".repeat(64),receipt.bytes());assertThatThrownBy(()->e.require(identity,plain,other)).isInstanceOf(EvidenceFailure.class);assertThatThrownBy(()->e.require(identity,new byte[]{1},receipt)).isInstanceOf(EvidenceFailure.class);assertThat(store.creates).isEqualTo(1);}
 private static final class Memory implements IndependentObjects {
  final Map<Key,byte[]> values=new ConcurrentHashMap<>();int creates;boolean lose,discard,corrupt;
  public boolean create(Key key,byte[] bytes){creates++;if(!discard)values.putIfAbsent(key,bytes.clone());if(lose)throw new EvidenceFailure("EVIDENCE_STORE_UNAVAILABLE");return true;}
  public Optional<byte[]> read(Key key){return Optional.ofNullable(values.get(key)).map(bytes->{byte[] copy=bytes.clone();if(corrupt)copy[copy.length-1]^=1;return copy;});}
  public Page list(Family family,int size,Key after){return new Page(values.keySet().stream().filter(k->k.family()==family).sorted(Comparator.comparing(Key::path)).limit(size).toList(),false);}
 }
}
